import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './LandingPage.css';

export default function LandingPage() {
  const nav = useNavigate();
  const [query, setQuery] = useState('');
  const [error, setError] = useState('');

  const handleSearch = (e) => {
    e.preventDefault();
    const value = query.trim();

    if (!value) {
      setError('Enter a document reference, title, or department to continue.');
      return;
    }

    setError('');
    nav('/login', { state: { searchTerm: value } });
  };

  return (
    <div className="landing-page">
      <header className="landing-header">
        <div className="landing-brand">
          <img src="/logo-dashboard.png" alt="Paper Tracking System" className="landing-logo" />
          <div>
            <div className="landing-brand-name">Paper Tracking System</div>
            <div className="landing-brand-sub">Municipality of Calape</div>
          </div>
        </div>

        <button type="button" className="btn btn-navy landing-login-btn" onClick={() => nav('/login')}>
          Log In
        </button>
      </header>

      <main className="landing-main">
        <div className="landing-copy">
          <span className="landing-eyebrow">Document search portal</span>
          <h1>Search by Document</h1>
          <p>
            Find papers, references, and tracking details from one clean starting point.
            Sign in when you need full tracking and department access.
          </p>
        </div>

        <form className="search-panel" onSubmit={handleSearch}>
          <label className="sr-only" htmlFor="document-search">Search by document</label>
          <div className="search-shell">
            <span className="search-icon" aria-hidden="true">⌕</span>
            <input
              id="document-search"
              className="search-input"
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search by document reference, title, or department"
            />
            <button type="submit" className="btn btn-navy search-btn">Search</button>
          </div>
          {error && <div className="search-error">{error}</div>}
          <div className="search-hint">Sign in to continue into the tracking workspace.</div>
        </form>
      </main>
    </div>
  );
}
